from invoices.model import Invoice


def subtotal_cents(invoice: Invoice) -> int:
    """Sum of quantity times unit price over all lines."""
    return sum(l.quantity * l.unit_price_cents for l in invoice.lines)


def average_line_price(invoice: Invoice) -> int:
    """Unweighted mean of unit_price_cents across the invoice lines, in cents.

    Each line counts once, regardless of quantity. The result is rounded
    down (floor division, so toward negative infinity) to a whole cent.
    An invoice with no lines returns 0.
    """
    if not invoice.lines:
        return 0
    return sum(l.unit_price_cents for l in invoice.lines) // len(invoice.lines)

